 "TX": {
  "name": "Texas",
  "remedy": "Expunction (non-convictions); order of nondisclosure (sealing from the public) for eligible convictions and deferred adjudication",
  "misdemeanor": {
   "eligible": true,
   "waitYears": 2,
   "waitFrom": "completion of the sentence (no wait if fine-only)",
   "automatic": false,
   "note": "A first-time misdemeanor conviction cannot be expunged, but you can ask the court for an order of nondisclosure, which hides it from the public: right away if the sentence was fine-only, otherwise 2 years after the sentence ends. A $28 fee applies; family-violence, sex, and certain violent offenses are excluded, and any prior conviction or deferred adjudication (other than fine-only traffic) bars relief.",
   "citation": "Tex. Gov't Code §§ 411.073, 411.0735, 411.074",
   "source_url": "https://ccresourcecenter.org/state-restoration-profiles/texas-restoration-of-rights-pardon-expungement-sealing/",
   "status": "corrected",
   "varies": false
  },
  "felony": {
   "eligible": false,
   "waitFrom": null,
   "automatic": false,
   "note": "A felony conviction cannot be expunged or sealed in Texas except through a pardon. If you got deferred adjudication instead of a conviction, you can petition for nondisclosure 5 years after discharge and dismissal.",
   "citation": "Tex. Code Crim. Proc. ch. 55A; Tex. Gov't Code § 411.0725",
   "source_url": "https://ccresourcecenter.org/state-restoration-profiles/texas-restoration-of-rights-pardon-expungement-sealing/",
   "status": "verified",
   "varies": false
  },
  "dui": {
   "eligible": "conditional",
   "waitYears": 2,
   "waitFrom": "completion of the sentence",
   "automatic": false,
   "note": "A first-offense DWI can be sealed by an order of nondisclosure only if your blood alcohol was below 0.15 and no crash involved another person. You must wait 2 to 5 years after finishing your sentence; the shorter wait applies if your sentence restricted your driving (e.g., ignition interlock) for at least 6 months.",
   "citation": "Tex. Gov't Code §§ 411.0731, 411.0736",
   "source_url": "https://ccresourcecenter.org/state-restoration-profiles/texas-restoration-of-rights-pardon-expungement-sealing/",
   "status": "corrected",
   "varies": true
  },
  "dismissed": {
   "eligible": true,
   "waitYears": 1,
   "waitFrom": "date of arrest (Class A/B misdemeanor); acquittal has no wait",
   "automatic": false,
   "note": "An acquittal can be expunged immediately. If the charge was never filed or was dismissed, you can seek expunction after a wait counted from your arrest: 180 days for a Class C misdemeanor, 1 year for a Class A or B misdemeanor, and 3 years for a felony (or sooner if the prosecutor certifies the records are no longer needed, or once the statute of limitations has run).",
   "citation": "Tex. Code Crim. Proc. arts. 55A.002, 55A.051-55A.053 (formerly art. 55.01, recodified eff. Jan. 1, 2025 by HB 4504)",
   "source_url": "https://ccresourcecenter.org/state-restoration-profiles/texas-restoration-of-rights-pardon-expungement-sealing/",
   "status": "corrected",
   "varies": true
  },
  "domestic": {
   "eligible": false,
   "waitFrom": null,
   "automatic": false,
   "note": "A family-violence conviction cannot be expunged, and offenses involving family violence are barred from orders of nondisclosure.",
   "citation": "Tex. Gov't Code § 411.074(b); Tex. Fam. Code § 71.004",
   "source_url": "https://ccresourcecenter.org/state-restoration-profiles/texas-restoration-of-rights-pardon-expungement-sealing/",
   "status": "verified",
   "varies": false
  },
  "sexual": {
   "eligible": false,
   "waitFrom": null,
   "automatic": false,
   "note": "Convictions or deferred adjudications for offenses requiring sex-offender registration cannot be expunged or sealed by nondisclosure.",
   "citation": "Tex. Gov't Code § 411.074(b); Tex. Code Crim. Proc. ch. 62",
   "source_url": "https://ccresourcecenter.org/state-restoration-profiles/texas-restoration-of-rights-pardon-expungement-sealing/",
   "status": "verified",
   "varies": false
  }
 },
